package com.jituileet.inputmethod;
import android.view.*;import android.widget.*;import android.content.*;
public final class ImeClipboardEditPanel extends LinearLayout {
 private final DrumstickImeService service; private final int index; private final EditText editor; private final boolean zh;
 public ImeClipboardEditPanel(DrumstickImeService s,int i,String text){super(s);service=s;index=i;zh=s.isChineseLanguagePublic();setOrientation(VERTICAL);setPadding(24,16,24,16);setBackgroundColor(Prefs.dark(s)?0xFF202124:0xFFFFFFFF);TextView t=new TextView(s);t.setText(zh?"编辑剪贴板":"Edit clipboard");t.setTextSize(22);addView(t,new LayoutParams(-1,60));editor=new EditText(s);editor.setText(text);editor.setTextSize(20);editor.setSingleLine(false);editor.setFocusable(true);addView(editor,new LayoutParams(-1,0,1));LinearLayout bar=new LinearLayout(s);Button save=new Button(s);save.setText(zh?"保存":"Save");save.setAllCaps(false);save.setOnClickListener(v->{ClipboardHistory.update(service,index,editor.getText().toString());try{android.content.ClipboardManager cm=(android.content.ClipboardManager)service.getSystemService(Context.CLIPBOARD_SERVICE);cm.setPrimaryClip(ClipData.newPlainText("Drumstick",editor.getText().toString()));}catch(Throwable ignored){}service.showClipboardHistoryPublic();});bar.addView(save,new LayoutParams(0,64,1));Button cancel=new Button(s);cancel.setText(zh?"取消":"Cancel");cancel.setAllCaps(false);cancel.setOnClickListener(v->service.showClipboardHistoryPublic());bar.addView(cancel,new LayoutParams(0,64,1));addView(bar,new LayoutParams(-1,72));postDelayed(()->editor.requestFocus(),80);}
}
